123	// GetEOL returns lifecycle data for a supported OS family and release.
124	// Releases with patch or minor suffixes match the corresponding modeled major release.
125	func GetEOL(family, release string) (EOL, bool) {
126		releases, ok := eolData[family]
127		if !ok {
128			return EOL{}, false
129		}
130	
131		release = strings.TrimSpace(release)
132		eol, ok := releases[release]
133		if !ok {
134			// OS detectors commonly append a patch/minor identifier to a modeled
135			// release (for example, 7.9 or 8.10). Match only on version separators.
136			bestMatch := ""
137			for candidate := range releases {
138				if len(candidate) <= len(bestMatch) || !strings.HasPrefix(release, candidate) {
139					continue
140				}
141				suffix := release[len(candidate):]
142				if strings.HasPrefix(suffix, ".") || strings.HasPrefix(suffix, "-") {
143					bestMatch = candidate
144				}
145			}
146			if bestMatch == "" {
147				return EOL{}, false
148			}
149			eol = releases[bestMatch]
150		}
151		eol.Ended = eol.IsStandardSupportEnded(time.Now())
152		return eol, true
153	}
