155	// EOLWarnings evaluates lifecycle data and returns warnings in display order.
156	func EOLWarnings(family, release string, now time.Time) []string {
157		if family == ServerTypePseudo || family == Raspbian {
158			return nil
159		}
160		eol, found := GetEOL(family, release)
161		if !found {
162			return []string{fmt.Sprintf("Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in 'Family: %s Release: %s'", family, release)}
163		}
164	
165		if !eol.IsStandardSupportEnded(now) {
166			if !eol.StandardSupportUntil.After(now) || !eol.StandardSupportUntil.After(now.AddDate(0, 3, 0)) {
167				return []string{fmt.Sprintf("Standard OS support will be end in 3 months. EOL date: %s", eol.StandardSupportUntil.Format("2006-01-02"))}
168			}
169			return nil
170		}
171	
172		warnings := []string{"Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended."}
173		if !eol.ExtendedSupportUntil.IsZero() {
174			if eol.IsExtendedSuppportEnded(now) {
175				warnings = append(warnings, "Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended.")
176			} else {
177				warnings = append(warnings, fmt.Sprintf("Extended support available until %s. Check the vendor site.", eol.ExtendedSupportUntil.Format("2006-01-02")))
178			}
179		}
180		return warnings
181	}
